sysauto_script.script:
/**
 * Scheduled job: CMDB Governance - nightly assessment.
 *
 * Queues one run; the async business rule executes it. Created INACTIVE, so
 * enable the job on sysauto_script when nightly assessment is wanted.
 */
;(function () {
    try {
        var connection = new GlideRecord('x_cmdbgov_app_connection')
        connection.addQuery('active', true)
        connection.orderBy('name')
        connection.setLimit(1)
        connection.query()

        if (!connection.next()) {
            gs.error('CMDB Governance nightly assessment: no active Governance Connection; nothing queued.')
            return
        }

        var run = new GlideRecord('x_cmdbgov_app_run')
        run.initialize()
        run.setValue('connection', connection.getUniqueValue())
        run.setValue('state', 'queued')
        var sysId = run.insert()

        if (sysId) {
            gs.info('CMDB Governance nightly assessment queued run ' + sysId + ' against "' + connection.getValue('name') + '".')
        } else {
            gs.error('CMDB Governance nightly assessment: could not insert the run record.')
        }
    } catch (e) {
        gs.error('CMDB Governance nightly assessment failed: ' + (e.message || e))
    }
})()
